#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 998244353;

struct Matrix {
    int n;
    vector<vector<int>> a;
    Matrix(int _n = 0) : n(_n) {
        a.assign(n, vector<int>(n, 0));
    }
    Matrix operator*(const Matrix &o) const {
        Matrix res(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 0) continue;
                for (int k = 0; k < n; k++) {
                    res.a[i][k] = (res.a[i][k] + (ll)a[i][j] * o.a[j][k]) % MOD;
                }
            }
        }
        return res;
    }
};

Matrix identity(int n) {
    Matrix I(n);
    for (int i = 0; i < n; i++) I.a[i][i] = 1;
    return I;
}

Matrix powmat(Matrix base, ll exp) {
    Matrix res = identity(base.n);
    while (exp > 0) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    ll m;
    cin >> n >> m;
    vector<string> words(n);
    for (int i = 0; i < n; i++) {
        cin >> words[i];
    }

    // Build adjacency list for each word
    vector<vector<int>> adj(n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (words[i].size() >= 2 && words[j].size() >= 2) {
                string s1 = words[i].substr(1);
                string s2 = words[j].substr(0, words[j].size() - 1);
                if (s1 == s2) {
                    adj[i].push_back(j);
                }
            }
        }
    }

    // Build transition matrix
    Matrix T(n);
    for (int i = 0; i < n; i++) {
        for (int j : adj[i]) {
            T.a[i][j] = 1;
        }
    }

    // Compute T^m
    Matrix Tm = powmat(T, m);

    // Sum all elements of Tm
    int ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            ans = (ans + Tm.a[i][j]) % MOD;
        }
    }

    cout << ans << endl;
    return 0;
}
