```cpp
#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <algorithm>
#include <cstring>
using namespace std;

const int MOD = 998244353;

typedef vector<vector<int>> Matrix;

Matrix multiply(const Matrix &a, const Matrix &b) {
    int n = a.size();
    int m = b[0].size();
    int k = b.size();
    Matrix c(n, vector<int>(m, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int l = 0; l < k; ++l) {
                c[i][j] = (c[i][j] + (long long)a[i][l] * b[l][j]) % MOD;
            }
        }
    }
    return c;
}

Matrix matrix_pow(Matrix a, long long power) {
    int n = a.size();
    Matrix result(n, vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        result[i][i] = 1;
    }
    while (power > 0) {
        if (power % 2 == 1) {
            result = multiply(result, a);
        }
        a = multiply(a, a);
        power /= 2;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<string> words(n);
    for (int i = 0; i < n; ++i) {
        cin >> words[i];
    }

    int max_len = 0;
    for (const string &w : words) {
        max_len = max(max_len, (int)w.length());
    }

    vector<int> dp(max_len + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= max_len; ++i) {
        for (const string &w : words) {
            int len = w.length();
            if (len <= i) {
                dp[i] = (dp[i] + dp[i - len]) % MOD;
            }
        }
    }

    Matrix transition(max_len + 1, vector<int>(max_len + 1, 0));
    for (int i = 0; i <= max_len; ++i) {
        for (const string &w : words) {
            int len = w.length();
            if (i + len <= max_len) {
                transition[i][i + len] = (transition[i][i + len] + 1) % MOD;
            }
        }
    }

    Matrix mat = matrix_pow(transition, m);
    long long result = 0;
    for (int i = 0; i <= max_len; ++i) {
        result = (result + (long long)dp[i] * mat[0][i]) % MOD;
    }

    cout << result << endl;
    return 0;
}
