#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

struct Matrix {
    int n;
    vector<vector<int>> mat;
    Matrix(int _n) : n(_n), mat(_n, vector<int>(_n, 0)) {}
    Matrix operator*(const Matrix &o) const {
        Matrix res(n);
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (mat[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    res.mat[i][j] = (res.mat[i][j] + (1LL * mat[i][k] * o.mat[k][j]) % MOD) % MOD;
                }
            }
        }
        return res;
    }
};

Matrix identity(int n) {
    Matrix id(n);
    for (int i = 0; i < n; i++) id.mat[i][i] = 1;
    return id;
}

Matrix pow_mod(Matrix base, long long exp) {
    Matrix res = identity(base.n);
    while (exp > 0) {
        if (exp % 2 == 1) res = res * base;
        base = base * base;
        exp /= 2;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    long long m;
    cin >> n >> m;

    vector<string> words(n);
    for (int i = 0; i < n; i++) {
        cin >> words[i];
    }

    // Build adjacency list for each word
    vector<vector<int>> adj(n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (words[i].size() >= 2 && words[j].size() >= 2) {
                string suffix = words[i].substr(words[i].size() - 2);
                string prefix = words[j].substr(0, 2);
                if (suffix == prefix) {
                    adj[i].push_back(j);
                }
            }
        }
    }

    // Build transition matrix
    Matrix trans(n);
    for (int i = 0; i < n; i++) {
        for (int j : adj[i]) {
            trans.mat[i][j] = 1;
        }
    }

    // Compute trans^(m-1)
    Matrix result = pow_mod(trans, m - 1);

    // Sum all entries
    int total = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            total = (total + result.mat[i][j]) % MOD;
        }
    }

    cout << total << endl;

    return 0;
}
