        vector<vector<int>> C(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (A[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    C[i][j] = (C[i][j] + (1LL * A[i][k] * B[k][j]) % MOD) % MOD;
                }
            }
        }
        return C;
    };

    // Matrix exponentiation
    auto power = [&](vector<vector<int>> base, long long exp) {
        int n = base.size();
        vector<vector<int>> result(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) result[i][i] = 1;
        while (exp > 0) {
            if (exp & 1) result = multiply(result, base);
            base = multiply(base, base);
            exp >>= 1;
        }
        return result;
    };

    vector<vector<int>> result = power(mat, m);

    // Answer: number of paths from (0,0) to (0,0) of length m
    cout << result[0][0] << endl;

    return 0;
