    int size = n;
    vector<vector<int>> adj(size, vector<int>(size, 0));
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (words[i].back() == words[j][0]) {
                adj[i][j] = 1;
            }
        }
    }

    // Matrix multiplication
    auto multiply = [](const vector<vector<int>>& a, const vector<vector<int>>& b) {
        int n = a.size();
        vector<vector<int>> c(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    c[i][j] = (c[i][j] + (ll)a[i][k] * b[k][j]) % MOD;
                }
            }
        }
        return c;
    };

    // Matrix exponentiation
    auto matrix_pow = [&](vector<vector<int>> mat, ll power) {
        int n = mat.size();
        vector<vector<int>> result(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            result[i][i] = 1;
        }
        while (power > 0) {
            if (power % 2 == 1) {
                result = multiply(result, mat);
            }
            mat = multiply(mat, mat);
            power /= 2;
        }
        return result;
    };

    if (m == 1) {
        cout << n % MOD << endl;
        return 0;
    }

    vector<vector<int>> mat_pow = matrix_pow(adj, m - 1);
    int total = 0;
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            total = (total + mat_pow[i][j]) % MOD;
        }
    }
    cout << total << endl;
    return 0;
}
