#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

struct Matrix {
    int n;
    vector<vector<int>> a;
    Matrix(int _n = 0) {
        n = _n;
        a.assign(n, vector<int>(n, 0));
    }
    Matrix operator*(const Matrix& other) const {
        Matrix res(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 0) continue;
                for (int k = 0; k < n; k++) {
                    res.a[i][k] = (res.a[i][k] + (1LL * a[i][j] * other.a[j][k]) % MOD) % MOD;
                }
            }
        }
        return res;
    }
};

Matrix identity(int n) {
    Matrix I(n);
    for (int i = 0; i < n; i++) I.a[i][i] = 1;
    return I;
}

Matrix power(Matrix base, long long exp) {
    Matrix result = identity(base.n);
    while (exp > 0) {
        if (exp % 2 == 1) result = result * base;
        base = base * base;
        exp /= 2;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    long long m;
    cin >> n >> m;

    vector<string> words(n);
    for (int i = 0; i < n; i++) {
        cin >> words[i];
    }

    // Collect all possible prefixes (states)
    set<string> prefixSet;
    prefixSet.insert("");
    for (string w : words) {
        for (int len = 1; len <= w.size(); len++) {
            prefixSet.insert(w.substr(0, len));
        }
    }

    vector<string> prefixes(prefixSet.begin(), prefixSet.end());
    int numStates = prefixes.size();
    map<string, int> stateIndex;
    for (int i = 0; i < numStates; i++) {
        stateIndex[prefixes[i]] = i;
    }

    // Build transition matrix
    Matrix trans(numStates);
    for (int i = 0; i < numStates; i++) {
        string s = prefixes[i];
        for (string w : words) {
            if (w.size() <= s.size()) continue;
            if (s == w.substr(0, s.size())) {
                string next = w.substr(0, s.size() + 1);
                if (prefixSet.count(next)) {
                    int j = stateIndex[next];
                    trans.a[i][j] = (trans.a[i][j] + 1) % MOD;
                }
            }
        }
    }

    // Compute trans^m
    Matrix result = power(trans, m);

    // Sum all paths from state 0 to any state
    int answer = 0;
    for (int j = 0; j < numStates; j++) {
        answer = (answer + result.a[0][j]) % MOD;
    }

    cout << answer << endl;

    return 0;
}
